 <body>
   <a class="skip-link" href="#main-content">Skip to main content</a>

   <main id="main-content" class="page-shell">
     <section class="hero" aria-labelledby="page-title">
       <p class="eyebrow">Multiple-select quiz</p>
       <h1 id="page-title">Computer Languages Quiz</h1>
       <p class="intro">Choose every answer that applies for each question, then submit your selections.</p>
     </section>

     <div id="quiz-root"></div>
   </main>

   <script>
     const quizQuestions = [
       {
         id: "general-purpose",
         prompt: "Which of these are general-purpose programming languages?",
         helpText: "Select all languages that are commonly used to build software across many domains.",
         choices: ["Python", "HTML", "JavaScript", "C++"]
       },
       {
         id: "web-standards",
         prompt: "Which languages are core technologies used directly by web browsers?",
         choices: ["HTML", "CSS", "SQL", "JavaScript"]
       },
       {
         id: "data-query",
         prompt: "Which of these languages are commonly associated with data querying or data analysis?",
         choices: ["SQL", "R", "Python", "Bash"]
       }
     ];

     function Choice({ questionId, value }) {
       const choiceId = `${questionId}-${value.toLowerCase().replace(/[^a-z0-9]+/g, "-")}`;

       return `
         <label class="choice" for="${choiceId}">
           <input id="${choiceId}" name="${questionId}" type="checkbox" value="${value}">
           <span>${value}</span>
         </label>
       `;
     }

     function QuestionField({ question, index }) {
       const headingId = `${question.id}-heading`;
       const helpId = question.helpText ? `${question.id}-help` : "";
       const describedBy = helpId ? ` aria-describedby="${helpId}"` : "";

       return `
         <div class="form-field">
           <fieldset aria-labelledby="${headingId}"${describedBy}>
             <legend id="${headingId}" class="question-heading">
               ${index + 1}. ${question.prompt}
             </legend>
             ${question.helpText ? `<p id="${helpId}" class="help-text">${question.helpText}</p>` : ""}
             <div class="choice-grid">
               ${question.choices.map((choice) => Choice({ questionId: question.id, value: choice })).join("")}
             </div>
           </fieldset>
         </div>
       `;
     }

     function QuizApp({ questions }) {
       return `
         <form id="quiz-form" class="quiz-card" aria-describedby="quiz-result">
           ${questions.map((question, index) => QuestionField({ question, index })).join("")}
           <div class="actions">
             <button class="submit-button" type="submit">Submit answers</button>
             <p id="quiz-result" class="result" aria-live="polite">No answers submitted yet.</p>
           </div>
         </form>
       `;
     }

     const quizRoot = document.querySelector("#quiz-root");
     quizRoot.innerHTML = QuizApp({ questions: quizQuestions });

     document.querySelector("#quiz-form").addEventListener("submit", (event) => {
       event.preventDefault();

       const selectedCount = quizQuestions.reduce((total, question) => {
         return total + document.querySelectorAll(`input[name="${question.id}"]:checked`).length;
       }, 0);

       const result = document.querySelector("#quiz-result");
       result.textContent = selectedCount === 1
         ? "Submitted 1 selected answer."
         : `Submitted ${selectedCount} selected answers.`;
     });
   </script>
 </body>
